import axios from "axios";
import { useEffect, useState } from "react";

function Main() {

    const [data, setData] = useState([]);
    useEffect(() => {
        const parseData = async() => {
            try {
                const response = await axios.get("http://localhost:8000/api/products/");
                return response.data.results; 
            } catch (error) {
                console.error("Ошибка при загрузке данных:", error);
                return []; 
            }
        }
        
        parseData().then(result => {
            setData(result);
        });
    }, []);
    return ( 
        <>

        <div class="out_container">
            <div class="container">
                <header>
                    <div class="header-left--item">
                        <div class="item item_logo"><img className="header__img_logo" src="images/logo.svg" alt="search" /></div>
                    </div>
                    <div class="header-right--item">
                        <div class="item item_3"><img className="header__img" src="images/search.svg" alt="search" /></div>
                        <div class="item item_4"><img className="header__img" src="images/profile.svg" alt="home" /></div>
                    </div>
                </header>
                <div class="afterheader">
                    <div class="afterheader__item">Home</div>
                    <div class="afterheader__item">Explore</div>
                    <div class="afterheader__item">Message</div>
                </div>
                <div class="main_body">
                   
                    
                </div>
                <div class="bottom__panel">
                        <div class="bottom__item bottom__item1"><img className="bottom__img" src="images/home.svg" alt="" /></div>
                        <div class="bottom__item bottom__item2"><img className="bottom__img" src="images/searchZh.svg" alt="" /></div>
                        <div class="bottom__item bottom__item3"><img className="plus__img" src="images/plus.svg" alt="" /></div>
                        <div class="bottom__item bottom__item4"><img className="bottom__img" src="images/message.svg" alt="" /></div>
                        <div class="bottom__item bottom__item5"><img className="bottom__img" src="images/message.svg" alt="" /></div>
                </div>
            </div>
        </div>
        </>
     );
}

export default Main;
